// Normalize the Gmail Trigger item into the same shape run.py / gmail_service.py build
const msg = $input.item.json;

const headers = {};
for (const h of (msg.payload?.headers || [])) {
  headers[h.name] = h.value;
}

function decodeBody(payload) {
  const data = payload?.body?.data;
  if (payload?.mimeType === 'text/plain' && data) {
    return Buffer.from(data, 'base64url').toString('utf-8');
  }
  if (payload?.mimeType === 'text/html' && data) {
    const html = Buffer.from(data, 'base64url').toString('utf-8');
    return html.replace(/<[^>]+>/g, ' ');
  }
  for (const part of (payload?.parts || [])) {
    const text = decodeBody(part);
    if (text && text.trim()) return text;
  }
  return '';
}

const body = decodeBody(msg.payload).slice(0, 50000);

return {
  json: {
    gmail_message_id: msg.id,
    sender: headers['From'] || 'unknown',
    subject: headers['Subject'] || '(no subject)',
    body,
    received_date: headers['Date'] ? new Date(headers['Date']).toISOString() : null
  }
};

// Merge the inserted email row (id) back with the original subject/body
// so downstream nodes have everything they need for the AI call and offer insert.
const emailRow = $input.item.json; // { id }
const original = $('Extract Email Fields').item.json;

return {
  json: {
    email_id: emailRow.id,
    subject: original.subject,
    body: original.body
  }
};

// Mirrors ai/analyzer.py: _extract_json + _safe_float + defaults
const prior = $('Attach email_id').item.json; // { email_id, subject, body }
const resp = $json;

let text = resp?.candidates?.[0]?.content?.parts?.[0]?.text || '';
text = text.trim().replace(/^```(json)?/, '').replace(/```$/, '').trim();

let data;
try {
  data = JSON.parse(text);
} catch (e) {
  const match = text.match(/\{[\s\S]*\}/);
  data = match ? JSON.parse(match[0]) : null;
}

if (!data) {
  throw new Error('Gemini returned no parseable JSON for email_id=' + prior.email_id);
}

function safeFloat(v, low = 0, high = 100) {
  const n = parseFloat(v);
  if (Number.isNaN(n)) return null;
  return Math.max(low, Math.min(high, n));
}

function parseExpiry(s) {
  if (!s) return null;
  const d = new Date(s);
  return Number.isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
}

return {
  json: {
    email_id: prior.email_id,
    brand: data.brand ?? null,
    company: data.company ?? null,
    category: data.category ?? null,
    subcategory: data.subcategory ?? null,
    offer_type: data.offer_type ?? null,
    discount_percentage: safeFloat(data.discount_percentage),
    coupon_code: data.coupon_code ?? null,
    expiry_date: parseExpiry(data.expiry_date),
    offer_value: data.offer_value ?? null,
    website: data.website_url || null,
    summary: data.summary ?? null,
    key_highlights: JSON.stringify(Array.isArray(data.key_highlights) ? data.key_highlights : [])
  }
};

